import numpy as np
def equation(t, x, v, params):
    w = params[0]; p = params[1]
    C = np.cos(w*t); S = np.sin(w*t)
    return (params[2] + params[3]*t + params[4]*C + params[5]*S + params[6]*np.exp(-t)
            + params[7]*v**p + params[8]*t*np.log(v) + params[9]*x*v)
